import { test, expect } from '@playwright/test';

test.describe('Table Row Highlight on Hover', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should highlight row on hover', async ({ page }) => {
    const row = page.getByRole('row', { name: 'Row Name' }); // Replace 'Row Name' with the actual row name
    await row.hover();
    const highlightedRow = await row.evaluate((element) => {
      return window.getComputedStyle(element).backgroundColor;
    });
    expect(highlightedRow).toBe('rgba(255, 255, 0, 1)'); // Replace with the actual highlight color
  });

  test('should not highlight row when not hovered', async ({ page }) => {
    const row = page.getByRole('row', { name: 'Row Name' }); // Replace 'Row Name' with the actual row name
    const defaultRowColor = await row.evaluate((element) => {
      return window.getComputedStyle(element).backgroundColor;
    });
    expect(defaultRowColor).not.toBe('rgba(255, 255, 0, 1)'); // Replace with the actual highlight color
  });
});
